import 'package:flutter/material.dart';
import 'package:grocery_pos/core/di/injection.dart';
import 'package:grocery_pos/features/pos/domain/pos_repository.dart';
import 'package:grocery_pos/features/products/domain/product_entity.dart';

class ProductsPage extends StatefulWidget { const ProductsPage({super.key}); @override State<ProductsPage> createState()=>_ProductsPageState(); }
class _ProductsPageState extends State<ProductsPage>{
  final repo=getIt<PosRepository>(); List<ProductEntity> products=[]; bool loading=true;
  @override void initState(){super.initState();_load();}
  Future<void> _load()async{setState(()=>loading=true);final r=await repo.getProducts().run();r.match((f)=>_msg(f.message),(p)=>products=p);if(mounted)setState(()=>loading=false);}
  void _msg(String x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x)));}
  @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(12),child:Column(children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[const Text('المنتجات',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),FilledButton.icon(onPressed:()=>_edit(),icon:const Icon(Icons.add),label:const Text('منتج'))]),const SizedBox(height:10),Expanded(child:loading?const Center(child:CircularProgressIndicator()):Card(child:ListView.separated(itemCount:products.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(c,i){final p=products[i];return ListTile(title:Text(p.name),subtitle:Text('${p.barcode} • مخزون ${p.quantity} • تكلفة ${p.costPrice.toStringAsFixed(2)}'),trailing:Text('${p.salePrice.toStringAsFixed(2)} د.ل'),onTap:()=>_edit(p));})))]));
  Future<void> _edit([ProductEntity? p])async{final name=TextEditingController(text:p?.name??'');final bar=TextEditingController(text:p?.barcode??'');final cost=TextEditingController(text:p?.costPrice.toString()??'0');final price=TextEditingController(text:p?.salePrice.toString()??'');final qty=TextEditingController(text:p?.quantity.toString()??'0');final min=TextEditingController(text:p?.minStock.toString()??'5');final save=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(p==null?'إضافة منتج':'تعديل منتج'),content:SizedBox(width:420,child:SingleChildScrollView(child:Column(children:[_f(name,'الاسم'),_f(bar,'الباركود'),_f(cost,'سعر التكلفة',num:true),_f(price,'سعر البيع',num:true),_f(qty,'الكمية',num:true),_f(min,'حد النقص',num:true)]))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حفظ'))]));if(save!=true)return;final entity=ProductEntity(id:p?.id??0,name:name.text.trim(),barcode:bar.text.trim(),costPrice:double.tryParse(cost.text)??0,salePrice:double.tryParse(price.text)??0,quantity:double.tryParse(qty.text)??0,minStock:double.tryParse(min.text)??0);final r=await repo.saveProduct(entity).run();r.match((f)=>_msg(f.message),(_)=>_load());}
  Widget _f(TextEditingController c,String label,{bool num=false})=>Padding(padding:const EdgeInsets.only(bottom:8),child:TextField(controller:c,keyboardType:num?TextInputType.number:null,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
}
